"""Test suite for django.utils.decorators module."""

from functools import wraps


def test_classonlymethod_raises_on_instance_access():
    """Test that classonlymethod raises AttributeError when accessed on instance."""
    from django.utils.decorators import classonlymethod

    class TestClass:
        @classonlymethod
        def class_method(cls):
            return "class"

    # Should work on class
    assert TestClass.class_method() == "class"

    # Should raise AttributeError on instance
    instance = TestClass()
    try:
        instance.class_method()
        assert False, "Should have raised AttributeError"
    except AttributeError as e:
        assert "This method is available only on the class, not on instances." in str(e)


