def test_multi_decorate_single_decorator():
    """Test _multi_decorate with a single decorator."""
    from django.utils.decorators import _multi_decorate

    def my_decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            return func(*args, **kwargs) + "_decorated"
        return wrapper

    class TestClass:
        def original_method(self):
            return "original"

    decorated = _multi_decorate(my_decorator, TestClass.original_method)
    instance = TestClass()
    result = decorated(instance)
    assert result == "original_decorated"


def test_multi_decorate_multiple_decorators():
    """Test _multi_decorate with multiple decorators."""
    from django.utils.decorators import _multi_decorate

    def decorator1(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            return func(*args, **kwargs) + "_d1"
        return wrapper

    def decorator2(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            return func(*args, **kwargs) + "_d2"
        return wrapper

    class TestClass:
        def original_method(self):
            return "original"

    decorated = _multi_decorate([decorator1, decorator2], TestClass.original_method)
    instance = TestClass()
    result = decorated(instance)
    # Decorators are applied in reverse order (list[::-1])
    assert result == "original_d2_d1"


