def test_make_middleware_decorator_with_args():
    """Test make_middleware_decorator passes args to middleware."""
    from django.utils.decorators import make_middleware_decorator

    received_args = []
    received_kwargs = {}

    class TestMiddleware:
        def __init__(self, view_func, *args, **kwargs):
            self.view_func = view_func
            received_args.extend(args)
            received_kwargs.update(kwargs)

        def process_request(self, request):
            return None

    decorator_factory = make_middleware_decorator(TestMiddleware)
    decorator = decorator_factory("arg1", kwarg="value")

    def dummy_view(request):
        return "response"

    wrapped = decorator(dummy_view)
