def test_method_decorator_wraps_function():
    """Test that method_decorator properly wraps functions."""
    from django.utils.decorators import method_decorator

    def my_decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            return func(*args, **kwargs)
        return wrapper

    def my_function(request):
        """Function docstring"""
        return "result"

    decorated = method_decorator(my_decorator)(my_function)
    assert decorated.__name__ == "my_function"
    assert decorated.__doc__ == "Function docstring"


