def test_make_middleware_decorator_template_response():
    """Test middleware with template response rendering."""
    from django.utils.decorators import make_middleware_decorator

    class TemplateResponse:
        def __init__(self, content):
            self.content = content
            self.callbacks = []

        def render(self):
            return self.content

        def add_post_render_callback(self, callback):
            self.callbacks.append(callback)

    class TestMiddleware:
        def __init__(self, view_func):
            self.view_func = view_func

        def process_template_response(self, request, response):
            return f"template_modified_{response.content}"

    decorator_factory = make_middleware_decorator(TestMiddleware)
    decorator = decorator_factory()

    def dummy_view(request):
        return TemplateResponse("template_content")

    wrapped = decorator(dummy_view)
    response = wrapped(None)
    assert response == "template_modified_template_content"


