def test_classonlymethod_inheritance():
    """Test classonlymethod works with inheritance."""
    from django.utils.decorators import classonlymethod

    class BaseClass:
        @classonlymethod
        def base_method(cls):
            return "base"

    class ChildClass(BaseClass):
        pass

    assert BaseClass.base_method() == "base"
    assert ChildClass.base_method() == "base"

    child_instance = ChildClass()
    try:
        child_instance.base_method()
        assert False, "Should have raised AttributeError"
    except AttributeError:
        pass


