def test_method_decorator_iterable_decorator():
    """Test method_decorator with iterable decorator."""
    from django.utils.decorators import method_decorator

    def decorator1(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            return func(*args, **kwargs) + "_i1"
        return wrapper

    def decorator2(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            return func(*args, **kwargs) + "_i2"
        return wrapper

    class MyClass:
        def my_method(self):
            return "method"

    MyClass = method_decorator([decorator1, decorator2], 'my_method')(MyClass)
    instance = MyClass()
    result = instance.my_method()
    assert result == "method_i2_i1"

