from django.test import SimpleTestCase


class TestModelBaseMetaclass(SimpleTestCase):
    """Tests for the ModelBase metaclass."""

    def test_01_subclass_exception_creation(self):
        """Test subclass_exception helper function creates proper exception classes."""
        from django.db.models.base import subclass_exception

        class DummyClass:
            __qualname__ = "DummyClass"

        exc_class = subclass_exception("MyException", (ValueError,), "test_module", DummyClass)

        self.assertEqual(exc_class.__module__, "test_module")
        self.assertIn("DummyClass.MyException", exc_class.__qualname__)
        self.assertTrue(issubclass(exc_class, ValueError))

    def test_02_has_contribute_to_class_bound_method(self):
        """Test _has_contribute_to_class detects bound methods."""
        from django.db.models.base import _has_contribute_to_class

        class MyClass:
            def contribute_to_class(self, cls, name):
                pass

        obj = MyClass()
        self.assertTrue(_has_contribute_to_class(obj))

        # Class itself should return False
        self.assertFalse(_has_contribute_to_class(MyClass))

    def test_03_modelbase_add_to_class(self):
        """Test ModelBase.add_to_class method."""
        from django.db.models.base import ModelBase

        class TestModel(metaclass=ModelBase):
            pass

        # Add a simple attribute
        TestModel.add_to_class('test_attr', 'test_value')
        self.assertEqual(TestModel.test_attr, 'test_value')

    def test_04_modelbase_prepare_abstract(self):
        """Test ModelBase._prepare handles abstract models."""
        from django.db.models.base import ModelBase, Model
        from django.conf import settings

        # Configure Django settings first
        if not settings.configured:
            settings.configure(
                DEBUG=True,
                DATABASES={'default': {'ENGINE': 'django.db.backends.sqlite3'}},
                INSTALLED_APPS=['tests.check_framework'],
            )

        # Abstract model setup would require full Django initialization
        # This test verifies the method exists and doesn't crash on basic call
        self.assertTrue(hasattr(ModelBase, '_prepare'))


