    def test_runshell_sigint_handler_restored(self):
        """Test that SIGINT handler is restored after runshell."""
        original_handler = signal.getsignal(signal.SIGINT)

        # Create a mock connection object
        mock_connection = mock.MagicMock()

        def _mock_super_runshell(*args, **kwargs):
            # Verify SIGINT is ignored during execution
            current_handler = signal.getsignal(signal.SIGINT)
            self.assertEqual(current_handler, signal.SIG_IGN)

        with mock.patch.object(DatabaseClient.__bases__[0], 'runshell', _mock_super_runshell):
            client = DatabaseClient(mock_connection)
            client.runshell([])

        # Handler should be restored to original
        self.assertEqual(original_handler, signal.getsignal(signal.SIGINT))

    def test_runshell_sigint_handler_is_ignored_during_execution(self):
        """Test that SIGINT is set to SIG_IGN during runshell execution."""
        # Create a mock connection object
        mock_connection = mock.MagicMock()

        def _mock_super_runshell(*args, **kwargs):
            current_handler = signal.getsignal(signal.SIGINT)
            self.assertEqual(current_handler, signal.SIG_IGN)

        with mock.patch.object(DatabaseClient.__bases__[0], 'runshell', _mock_super_runshell):
            client = DatabaseClient(mock_connection)
            client.runshell([])

