class TestWrapInPandasContainer:
    """Tests for _wrap_in_pandas_container function."""

    def test_wrap_ndarray_to_dataframe(self):
        """Test wrapping ndarray to DataFrame."""
        from sklearn.utils._set_output import _wrap_in_pandas_container

        data = np.array([[1, 2], [3, 4]])
        result = _wrap_in_pandas_container(data, columns=["a", "b"])

        assert hasattr(result, "columns")
        assert list(result.columns) == ["a", "b"]

    def test_wrap_sparse_raises_error(self):
        """Test that sparse data raises ValueError."""
        from scipy.sparse import csr_matrix
        from sklearn.utils._set_output import _wrap_in_pandas_container

        sparse_data = csr_matrix([[1, 2], [3, 4]])
        with pytest.raises(ValueError, match="Pandas output does not support sparse data"):
            _wrap_in_pandas_container(sparse_data, columns=["a", "b"])

    def test_wrap_callable_columns_success(self):
        """Test wrapping with callable columns that succeeds."""
        from sklearn.utils._set_output import _wrap_in_pandas_container

        data = np.array([[1, 2], [3, 4]])
        result = _wrap_in_pandas_container(data, columns=lambda: ["x", "y"])

        assert hasattr(result, "columns")
        assert list(result.columns) == ["x", "y"]

    def test_wrap_callable_columns_raises(self):
        """Test wrapping with callable columns that raises exception."""
        from sklearn.utils._set_output import _wrap_in_pandas_container

        data = np.array([[1, 2], [3, 4]])
        result = _wrap_in_pandas_container(data, columns=lambda: (_ for _ in ()).throw(ValueError("test")))

        # Should handle the exception gracefully and use None columns
        assert hasattr(result, "columns")

    def test_wrap_existing_dataframe_with_columns(self):
        """Test wrapping existing DataFrame with new columns."""
        from sklearn.utils._set_output import _wrap_in_pandas_container
        import pandas as pd

        df = pd.DataFrame([[1, 2], [3, 4]], columns=["old1", "old2"])
        result = _wrap_in_pandas_container(df, columns=["new1", "new2"])

        assert list(result.columns) == ["new1", "new2"]

    def test_wrap_existing_dataframe_no_columns(self):
        """Test wrapping existing DataFrame without changing columns."""
        from sklearn.utils._set_output import _wrap_in_pandas_container
        import pandas as pd

        df = pd.DataFrame([[1, 2], [3, 4]], columns=["keep1", "keep2"])
        result = _wrap_in_pandas_container(df, columns=None)

        assert list(result.columns) == ["keep1", "keep2"]

    def test_wrap_with_index_parameter(self):
        """Test wrapping with index parameter."""
        from sklearn.utils._set_output import _wrap_in_pandas_container

        data = np.array([[1, 2], [3, 4]])
        idx = [10, 20]
        result = _wrap_in_pandas_container(data, columns=["a", "b"], index=idx)

        assert list(result.index) == idx

    def test_wrap_dataframe_ignores_index(self):
        """Test that index is ignored when data is already DataFrame."""
        from sklearn.utils._set_output import _wrap_in_pandas_container
        import pandas as pd

        df = pd.DataFrame([[1, 2], [3, 4]], columns=["a", "b"])
        idx = [10, 20]
        result = _wrap_in_pandas_container(df, columns=None, index=idx)

        # Index should remain unchanged (default RangeIndex)
        assert len(result) == 2


