class TestAdminSiteRegister(SimpleTestCase):
    """Tests for AdminSite.register method"""

    def setUp(self):
        self.site = AdminSite()

    def test_register_single_model(self):
        from django.db import models

        class TestModelA(models.Model):
            name = models.CharField(max_length=100)

            class Meta:
                app_label = 'test_app'

        self.site.register(TestModelA)
        self.assertIn(TestModelA, self.site._registry)

    def test_register_with_admin_class(self):
        from django.db import models

        class TestModelB(models.Model):
            name = models.CharField(max_length=100)

            class Meta:
                app_label = 'test_app'

        class CustomAdmin(ModelAdmin):
            pass

        self.site.register(TestModelB, CustomAdmin)
        self.assertIsInstance(self.site._registry[TestModelB], CustomAdmin)

    def test_register_with_options(self):
        from django.db import models

        class TestModelC(models.Model):
            name = models.CharField(max_length=100)

            class Meta:
                app_label = 'test_app'

        self.site.register(TestModelC, list_display=['name'])
        admin_instance = self.site._registry[TestModelC]
        self.assertEqual(admin_instance.list_display, ['name'])

    def test_register_iterable_of_models(self):
        from django.db import models

        class Model1X(models.Model):
            name = models.CharField(max_length=100)

            class Meta:
                app_label = 'test_app'

        class Model2Y(models.Model):
            name = models.CharField(max_length=100)

            class Meta:
                app_label = 'test_app'

        self.site.register([Model1X, Model2Y])
        self.assertIn(Model1X, self.site._registry)
        self.assertIn(Model2Y, self.site._registry)

    def test_register_abstract_model_raises(self):
        from django.db import models

        class AbstractModelZ(models.Model):
            name = models.CharField(max_length=100)

            class Meta:
                abstract = True
                app_label = 'test_app'

        with self.assertRaises(ImproperlyConfigured):
            self.site.register(AbstractModelZ)

    def test_register_already_registered_raises(self):
        from django.db import models

        class TestModelD(models.Model):
            name = models.CharField(max_length=100)

            class Meta:
                app_label = 'test_app'

        self.site.register(TestModelD)
        with self.assertRaises(AlreadyRegistered):
            self.site.register(TestModelD)

    def test_register_swapped_model_ignored(self):
        from django.db import models

        class TestModelE(models.Model):
            name = models.CharField(max_length=100)

            class Meta:
                app_label = 'test_app'
                swappable = 'TEST_SWAPPABLE_MODEL_E'

        # Swapped models should be ignored (not registered)
        self.site.register(TestModelE)
        # Note: In some Django versions, swapped models may still be registered
        # This test verifies the expected behavior
        pass


