class TestCoeffIsNeg:
    """Tests for _coeff_isneg function."""

    def test_negative_number(self):
        from sympy.core.function import _coeff_isneg
        assert _coeff_isneg(Rational(-3)) is True

    def test_positive_number(self):
        from sympy.core.function import _coeff_isneg
        assert _coeff_isneg(Rational(3)) is False

    def test_negative_pi(self):
        from sympy.core.function import _coeff_isneg
        assert _coeff_isneg(-3 * S.Pi) is True

    def test_positive_pi(self):
        from sympy.core.function import _coeff_isneg
        assert _coeff_isneg(3 * S.Pi) is False

    def test_negative_oo(self):
        from sympy.core.function import _coeff_isneg
        assert _coeff_isneg(-oo) is True

    def test_symbol_with_negative_assumption(self):
        from sympy.core.function import _coeff_isneg
        n = Symbol('n', negative=True)
        assert _coeff_isneg(n) is False

    def test_matrix_expression_negative(self):
        from sympy.core.function import _coeff_isneg
        A = MatrixSymbol("A", 3, 3)
        assert _coeff_isneg(-sqrt(2)*A) is True

    def test_matrix_expression_positive(self):
        from sympy.core.function import _coeff_isneg
        A = MatrixSymbol("A", 3, 3)
        assert _coeff_isneg(sqrt(2)*A) is False


